import{rotate,externalCamera}from'./navigation.mjs?v=8j';import{buildShip}from'./scene.mjs?v=8j';
export function unrotate(d,yaw,pitch){const x=Math.cos(yaw)*d[0]-Math.sin(yaw)*d[2],z=Math.sin(yaw)*d[0]+Math.cos(yaw)*d[2];return[x,Math.cos(pitch)*d[1]-Math.sin(pitch)*z,Math.sin(pitch)*d[1]+Math.cos(pitch)*z];}
const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0);
// These are unbent coordinate navigation aids, never claimed optical images.
export function markerProjection(point,nav,external,width,height,bounds={}){
 let d=unrotate(point.map((x,i)=>x-nav.position[i]),nav.yaw,nav.pitch),camera=bounds.camera??(external?externalCamera(nav):{eye:[0,0,0],right:rotate([1,0,0],nav.lookYaw,nav.lookPitch),up:rotate([0,1,0],nav.lookYaw,nav.lookPitch),forward:rotate([0,0,1],nav.lookYaw,nav.lookPitch)});d=d.map((x,i)=>x-camera.eye[i]);
 if(Math.hypot(...d)<1e-12)return{x:width/2,y:height/2,edge:false,behind:false,angle:0};
 const sx=dot(d,camera.right),sy=dot(d,camera.up),z=dot(d,camera.forward),focal=.5/Math.tan(nav.fov*Math.PI/360);let dx=sx/Math.max(.001,Math.abs(z))*focal*height,dy=-sy/Math.max(.001,Math.abs(z))*focal*height;
 if(z<=0&&Math.hypot(dx,dy)<1)dy=height;const left=bounds.left??28,right=bounds.right??width-28,top=bounds.top??Math.min(168,height*.3),bottom=bounds.bottom??height-90,edge=z<=0||width/2+dx<left||width/2+dx>right||height/2+dy<top||height/2+dy>bottom;
 if(edge){const t=Math.min(dx>0?(right-width/2)/dx:dx<0?(left-width/2)/dx:Infinity,dy>0?(bottom-height/2)/dy:dy<0?(top-height/2)/dy:Infinity);dx*=t;dy*=t;}
 return{x:width/2+dx,y:height/2+dy,edge,behind:z<=0,angle:Math.atan2(dy,dx)*180/Math.PI};
}
// Steering directions use the ship frame, independent of where the camera looks.
export function courseDirections(nav,point){
 const delta=point.map((x,i)=>x-nav.position[i]),distance=Math.hypot(...delta);if(distance<1e-12)return{yaw:0,pitch:0,angle:0,distance,text:'At target'};
 const yaw=Math.atan2(Math.sin(Math.atan2(delta[0],delta[2])-nav.yaw),Math.cos(Math.atan2(delta[0],delta[2])-nav.yaw))*180/Math.PI,pitch=(Math.atan2(delta[1],Math.hypot(delta[0],delta[2]))-nav.pitch)*180/Math.PI,forward=rotate([0,0,1],nav.yaw,nav.pitch),angle=Math.acos(Math.max(-1,Math.min(1,dot(forward,delta)/distance)))*180/Math.PI;
 const parts=[];if(Math.abs(yaw)>3)parts.push((yaw>0?'Right ':'Left ')+Math.round(Math.abs(yaw))+'°');if(Math.abs(pitch)>3)parts.push((pitch>0?'climb ':'descend ')+Math.round(Math.abs(pitch))+'°');return{yaw,pitch,angle,distance,text:parts.length?parts.join(' · '):'On course'};
}
const isoRight=[.8,0,.6],isoUp=[-.24,.916515139,.32],isoForward=[-.549909083,-.4,.733212111];
export function attitudeTriangles(yaw,pitch){const mesh=buildShip(),faces=[];for(let i=0;i<mesh.length;i+=30){const points=[0,10,20].map(j=>rotate(Array.from(mesh.slice(i+j,i+j+3)),yaw,pitch)),normal=rotate(Array.from(mesh.slice(i+3,i+6)),yaw,pitch),shade=.3+.7*Math.abs(dot(normal,[.4,.8,-.4])),color=Array.from(mesh.slice(i+6,i+9)).map(x=>Math.min(255,Math.round(x*shade*330)));faces.push({points:points.map(p=>[75+dot(p,isoRight)*72,75-dot(p,isoUp)*72]),depth:points.reduce((s,p)=>s+dot(p,isoForward),0),color:'rgb('+color.join(',')+')'});}return faces.sort((a,b)=>b.depth-a.depth);}
export function mountAttitude(svg){const ns='http://www.w3.org/2000/svg',ship=document.createElementNS(ns,'g'),axes=document.createElementNS(ns,'g');svg.append(axes,ship);const paths=attitudeTriangles(0,0).map(()=>{const p=document.createElementNS(ns,'path');ship.append(p);return p;});for(const[point,label,color]of[[[.75,0,0],'+X','#ec9b7e'],[[0,.75,0],'+Y','#a3e0bc'],[[0,0,.75],'+Z','#8fbded']]){const x=75+dot(point,isoRight)*72,y=75-dot(point,isoUp)*72,line=document.createElementNS(ns,'line'),text=document.createElementNS(ns,'text');for(const[k,v]of Object.entries({x1:75,y1:75,x2:x,y2:y,stroke:color,'stroke-opacity':.55}))line.setAttribute(k,v);text.setAttribute('x',x);text.setAttribute('y',y-5);text.setAttribute('fill',color);text.textContent=label;axes.append(line,text);}return(yaw,pitch)=>{attitudeTriangles(yaw,pitch).forEach((f,i)=>{paths[i].setAttribute('d',f.points.map((p,j)=>(j?'L':'M')+p.map(x=>x.toFixed(1)).join(' ')).join('')+'Z');paths[i].setAttribute('fill',f.color);});svg.setAttribute('aria-label','3D ship orientation: heading '+(yaw*180/Math.PI).toFixed(0)+' degrees, pitch '+(pitch*180/Math.PI).toFixed(0)+' degrees. World axes fixed.');};}
